UPDATE tickets SET category=#{category}, status=#{status}, assignee_id=#{assigneeId},
  related_ticket_id=#{relatedTicketId}, resolution_code=#{resolutionCode},
  version=version+1, updated_at=UTC_TIMESTAMP(6), completed_at=#{completedAt} WHERE id=#{id} AND version=#{version}

